insert into _tpl values
('BASE', $j${"u":"kUA/L","b":"S","bs":"IM","lo":"-","hi":"sensitisation to {N}","s":"A result of 0.35 kUA/L or above shows sensitisation to {N}. Higher levels make a true allergy more likely, but the level does not predict how severe a reaction will be.","gl":"Below 0.35 kUA/L means no sensitisation to {N} was detected. This makes an IgE-mediated allergy unlikely, but it does not rule out other types of reaction.","gh":"A level of 0.35 kUA/L or more shows sensitisation to {N}. It points to allergy only when it matches your symptoms after exposure.","a":"Recent exposure, cross-reactivity with related allergens, very high total IgE and the laboratory method used. Antihistamines do not affect this blood test.","rr":{"both":{"normal":["< 0.35","Negative (class 0)","No sensitisation detected."],"borderline":["0.35–0.69","Low (class 1)","Low-level sensitisation. Often of no clinical significance."],"elevated":["0.70–3.49","Moderate (class 2)","Sensitisation. Its relevance depends on your symptoms."],"high":["3.50–17.49","High (class 3)","Clear sensitisation. Allergy is more likely if your symptoms fit."],"veryHigh":["≥ 17.50","Very high (class 4 to 6)","Strong sensitisation. Discuss the result with an allergy specialist."]}},"z":["Total IgE","Specific IgE"],"i":"🛡️"}$j$),
('F', $j${"w":"The level of IgE antibodies in your blood that recognise {N}. A raised level shows sensitisation, which means your immune system has made allergy antibodies to this food.","y":"It helps confirm or rule out an IgE-mediated allergy to {N} when read alongside your history of reactions. Sensitisation without symptoms is common and does not mean you need to avoid the food.","r":"Usually tested once. An allergy specialist may repeat it every 12 to 24 months to check whether a childhood food allergy is resolving.","ug":"Call 999 if you have swelling of the lips, tongue or throat, difficulty breathing, wheeze or feel faint after eating. Use your adrenaline auto-injector first if you have one.","im":"Do not cut foods from your diet on the basis of this test alone. Ask your GP about referral to an allergy service, which can confirm the diagnosis and give you an allergy action plan.","c":["Food allergy","Anaphylaxis","Atopic eczema"],"x":["Hives (urticaria)","Itching or swelling in the mouth","Swelling of the lips or face","Vomiting or abdominal pain","Wheeze or breathlessness"],"f":["Check food labels if a clinician confirms allergy","Tell restaurants and caterers about confirmed allergies","Carry prescribed adrenaline auto-injectors at all times"],"t":["Sensitisation is common without allergy. A positive result needs to match a clear history of reactions after eating the food.","Allergen component tests can help separate a true food allergy from cross-reactivity with pollen."]}$j$),
('P', $j${"w":"The level of IgE antibodies in your blood that recognise {N}. A raised level shows sensitisation to this pollen.","y":"It helps identify which pollen may be causing seasonal hay fever or asthma. This guides treatment and, for some people, allergen immunotherapy.","r":"Usually tested once. Repeat only if your symptoms change or before allergen immunotherapy.","ug":"Seek urgent help if you have severe breathlessness or wheeze that does not settle with your reliever inhaler.","im":"Antihistamines and steroid nasal sprays treat most symptoms. Ask your GP about referral to an allergy service if symptoms are severe, as allergen immunotherapy may help.","c":["Allergic rhinitis (hay fever)","Allergic conjunctivitis","Asthma"],"x":["Sneezing","Runny or blocked nose","Itchy, watery eyes","Cough or wheeze"],"f":["Check daily pollen forecasts","Keep windows closed on high-pollen days","Shower and change clothes after time outdoors","Wear wraparound sunglasses outdoors"],"t":["Pollen seasons vary by plant, so the timing of your symptoms helps show which pollen is relevant.","Sensitisation to several pollens is often due to shared proteins, which component tests can identify."],"i":"🌿"}$j$),
('D', $j${"w":"The level of IgE antibodies in your blood that recognise {N}. A raised level shows sensitisation to this mite.","y":"Mite allergy is a common cause of year-round rhinitis, asthma and eczema flares. Knowing you are sensitised helps target avoidance and treatment.","r":"Usually tested once. Repeat only if your symptoms change or before allergen immunotherapy.","ug":"Seek urgent help if you have severe breathlessness or wheeze that does not settle with your reliever inhaler.","im":"Mite-reduction measures, antihistamines, steroid nasal sprays and asthma treatment help most people. An allergy service can advise whether immunotherapy is suitable.","c":["Allergic rhinitis","Asthma","Atopic eczema"],"x":["Year-round blocked or runny nose","Sneezing, often worse in the morning","Cough or wheeze","Itchy eyes","Eczema flares"],"f":["Use allergen-proof covers on mattresses and pillows","Wash bedding weekly at 60°C","Keep indoor humidity low and air rooms daily","Choose hard floors over carpets where possible"],"t":["Storage mites live in grain, flour and damp homes and can cross-react with house dust mites.","Mite allergy usually causes symptoms all year, unlike pollen allergy."]}$j$),
('E', $j${"w":"The level of IgE antibodies in your blood that recognise {N}. A raised level shows sensitisation to allergens from this animal.","y":"It helps confirm whether contact with this animal is causing rhinitis, asthma or skin symptoms. This is useful before getting a pet or for people who work with animals.","r":"Usually tested once. Repeat only if your symptoms or exposure change.","ug":"Seek urgent help if you have severe breathlessness or wheeze that does not settle with your reliever inhaler.","im":"Reducing contact with the animal is the most effective step. Antihistamines, steroid nasal sprays and asthma treatment help control symptoms. Ask your GP about an allergy referral if symptoms are hard to control.","c":["Allergic rhinitis","Asthma","Allergic conjunctivitis","Contact urticaria"],"x":["Sneezing and runny nose","Itchy, watery eyes","Wheeze or chest tightness","Itchy rash after contact"],"f":["Keep animals out of the bedroom","Use a HEPA air filter","Wash your hands after handling animals","Vacuum often with a HEPA-filter vacuum"],"t":["Animal allergens are sticky and airborne, so they stay in homes for months after an animal has gone.","Allergens from related animals can cross-react, for example between cats and other furry pets."]}$j$),
('M', $j${"w":"The level of IgE antibodies in your blood that recognise {N}. A raised level shows sensitisation to this mould.","y":"Mould allergy can cause rhinitis and asthma that may be worse in damp homes or in late summer and autumn. Identifying it helps target avoidance and treatment.","r":"Usually tested once. Repeat only if your symptoms change or your clinician advises it.","ug":"Seek urgent help if you have severe breathlessness or wheeze that does not settle with your reliever inhaler.","im":"Reducing damp and mould at home helps. Antihistamines, steroid nasal sprays and asthma treatment control most symptoms.","c":["Allergic rhinitis","Asthma"],"x":["Sneezing and blocked nose","Cough or wheeze","Itchy eyes","Symptoms worse in damp places or in autumn"],"f":["Fix damp and condensation at home","Ventilate kitchens and bathrooms","Avoid raking leaves and handling compost","Avoid drying clothes indoors where possible"],"t":["Severe asthma with mould sensitisation can be linked to fungal airway disease, which needs specialist review.","Outdoor mould spores peak in warm, humid weather and in autumn."]}$j$),
('V', $j${"w":"The level of IgE antibodies in your blood that recognise {N}. A raised level shows sensitisation to this venom.","y":"It helps confirm which insect caused a sting reaction. This guides decisions about venom immunotherapy, which greatly reduces the risk of future severe reactions.","r":"Usually tested once after a reaction, ideally at least 2 to 4 weeks after the sting. Your allergy specialist may repeat it during venom immunotherapy.","ug":"Call 999 if you have swelling of the face or throat, difficulty breathing, dizziness or collapse after a sting. Use your adrenaline auto-injector first if you have one.","im":"Anyone who has had a severe sting reaction should be referred to an allergy service. Venom immunotherapy can reduce the risk of anaphylaxis from future stings.","c":["Venom allergy","Anaphylaxis","Large local sting reactions"],"x":["Swelling well beyond the sting site","Hives over the body","Breathlessness or wheeze","Dizziness or fainting"],"f":["Wear shoes outdoors","Cover food and drinks outdoors","Keep away from nests and hives","Carry prescribed adrenaline auto-injectors"],"t":["A raised level after a sting reaction should be read alongside baseline serum tryptase.","Positive results to both bee and wasp venom can be due to cross-reactivity, and component tests can clarify this."],"z":["Serum Tryptase","Total IgE","Specific IgE"]}$j$),
('B', $j${"w":"The level of IgE antibodies in your blood that recognise {N}, a tick that lives where pigeons nest.","y":"Pigeon tick bites can cause severe allergic reactions, including anaphylaxis, in people who live or work near pigeon roosts. A raised level supports this diagnosis.","r":"Usually tested once after a suspected reaction.","ug":"Call 999 if you have swelling of the face or throat, difficulty breathing or feel faint after a bite.","im":"Removing pigeon nests and treating the building for ticks prevents further bites. An allergy service can advise on an emergency plan.","c":["Tick bite allergy","Anaphylaxis"],"x":["Itchy swelling around bites","Hives","Breathlessness","Dizziness or fainting"],"f":["Have pigeon nests near your home removed professionally","Seal gaps where pigeons roost"],"t":["Bites usually happen at night in homes where pigeons nest in the loft or roof space."],"z":["Serum Tryptase","Total IgE"]}$j$),
('IN', $j${"w":"The level of IgE antibodies in your blood that recognise {N}. A raised level shows sensitisation to cockroach allergens.","y":"Cockroach allergens in household dust can trigger asthma and rhinitis. A raised level helps explain year-round symptoms in homes with cockroaches.","r":"Usually tested once. Repeat only if your symptoms or exposure change.","ug":"Seek urgent help if you have severe breathlessness or wheeze that does not settle with your reliever inhaler.","im":"Pest control and removing food debris lower allergen levels. Asthma and rhinitis treatments control symptoms.","c":["Asthma","Allergic rhinitis"],"x":["Wheeze","Cough","Blocked or runny nose","Sneezing"],"f":["Use professional pest control","Store food in sealed containers","Fix leaks and remove clutter"],"t":["Cockroach sensitisation can cross-react with dust mites and shellfish because they share tropomyosin proteins."]}$j$),
('L', $j${"w":"The level of IgE antibodies in your blood that recognise {N}, the natural rubber from the rubber tree (Hevea brasiliensis).","y":"Latex allergy can cause reactions to gloves, balloons, condoms and medical equipment, and these can be severe. Knowing you are sensitised allows safe planning for medical and dental care.","r":"Usually tested once. Repeat only if your clinician advises it.","ug":"Call 999 if you have swelling of the face or throat, difficulty breathing or feel faint after contact with latex.","im":"Avoid latex if allergy is confirmed and tell all healthcare and dental teams. Some people with latex allergy also react to banana, avocado, kiwi and chestnut.","c":["Latex allergy","Contact urticaria","Anaphylaxis","Latex-fruit syndrome"],"x":["Itching or hives where latex touched the skin","Sneezing or wheeze around latex","Swelling of the lips or face"],"f":["Use non-latex gloves","Tell healthcare and dental teams about your allergy","Wear a medical alert bracelet if advised"],"t":["Healthcare workers and people who had many operations in childhood have a higher risk of latex allergy.","Latex extract tests can be positive through cross-reactivity with plant proteins, so component tests can help."]}$j$);
