insert into _ov values
('Alpha-lactalbumin', $j${"w":"The level of IgE antibodies to alpha-lactalbumin (Bos d 4), a whey protein in cow's milk.","y":"It helps assess cow's milk allergy. Alpha-lactalbumin is broken down by heat, so people sensitised mainly to it often tolerate milk baked into foods.","t":["Results are best read alongside casein and beta-lactoglobulin to judge the overall pattern of milk sensitisation."]}$j$),
('Beta-lactoglobulin', $j${"w":"The level of IgE antibodies to beta-lactoglobulin (Bos d 5), a whey protein in cow's milk.","y":"It helps assess cow's milk allergy. Beta-lactoglobulin is broken down by heat, so people sensitised mainly to it often tolerate milk baked into foods.","t":["Results are best read alongside casein and alpha-lactalbumin to judge the overall pattern of milk sensitisation."]}$j$),
('Bovine Serum Albumin', $j${"w":"The level of IgE antibodies to bovine serum albumin (Bos d 6), a protein found in cow's milk and beef.","y":"Sensitisation to this protein can explain reactions to both cow's milk and undercooked beef. It is broken down by thorough cooking.","t":["Bovine serum albumin is similar to albumins in other animals, so it can cross-react with other meats and animal dander."]}$j$),
('Casein', $j${"w":"The level of IgE antibodies to casein (Bos d 8), the main protein in cow's milk.","y":"Casein survives heating, so high levels are linked with milk allergy that persists and with reactions to baked milk products.","t":["High casein IgE is linked with a lower chance of tolerating baked milk, so challenges are planned with care.","Casein from cow's milk cross-reacts strongly with goat's and sheep's milk."]}$j$),
('Peanut Component (Ara h 2) IgE', $j${"w":"The level of IgE antibodies to Ara h 2, a storage protein in peanut.","y":"IgE to Ara h 2 predicts true peanut allergy more accurately than IgE to whole peanut extract. It helps separate clinical allergy from harmless cross-reactivity with pollen.","t":["Sensitisation to whole peanut without Ara h 2 is often due to cross-reactivity with birch or grass pollen.","Ara h 2 levels support, but do not replace, a specialist assessment or food challenge."],"z":["Peanut","Total IgE","Specific IgE"]}$j$),
('Gluten', $j${"t":["This test looks for an IgE-mediated wheat allergy. It does not test for coeliac disease, which needs a tissue transglutaminase (tTG) antibody test while you are eating gluten.","Sensitisation to wheat proteins can be linked with reactions that occur only when eating is followed by exercise."],"c":["Wheat allergy","Food-dependent exercise-induced anaphylaxis","Anaphylaxis"]}$j$),
('Wheat flour', $j${"t":["This test looks for an IgE-mediated wheat allergy. It does not test for coeliac disease, which needs a tissue transglutaminase (tTG) antibody test while you are eating gluten.","Grass pollen sensitisation can cause a positive wheat result without wheat allergy."]}$j$),
('Herring worm (specific IgE)', $j${"w":"The level of IgE antibodies to Anisakis simplex (herring worm), a parasite found in raw or undercooked fish.","y":"Anisakis can cause allergic reactions after eating fish even when the fish itself is not the allergen. A raised level helps explain reactions after fish meals.","c":["Anisakis allergy","Food allergy","Anaphylaxis"],"t":["Freezing fish at -20°C for at least 24 hours kills the parasite, but some people still react to its heat-stable allergens.","Anisakis shares proteins with shellfish and dust mites, so cross-reactivity is possible."]}$j$),
('Malassezia sympodialis', $j${"y":"Sensitisation to Malassezia is linked with atopic eczema, especially on the head, neck and upper body. A raised level can guide treatment with antifungal creams or shampoos.","c":["Atopic eczema (head and neck)","Seborrhoeic dermatitis"],"x":["Itchy eczema on the head, neck or upper body","Flaky or scaly skin"],"f":["Use antifungal shampoos or creams if your clinician advises","Keep skin moisturised"],"t":["Malassezia sensitisation is common in adults with head and neck eczema and rare in people without eczema."],"ug":"Seek prompt medical advice if eczema becomes weepy, crusted or painful, as this can mean infection.","im":"Antifungal treatment alongside usual eczema care can help when Malassezia sensitisation is present."}$j$),
('Male dog urine (incl. Can f 5) (specific IgE)', $j${"w":"The level of IgE antibodies to Can f 5, a protein made by the prostate gland and found in the urine of male dogs.","y":"People sensitised only to Can f 5 may tolerate female dogs or neutered male dogs. This helps when choosing a pet.","t":["Can f 5 sensitisation without sensitisation to other dog allergens suggests reactions mainly to entire male dogs."]}$j$),
('Weeping fig (specific IgE)', $j${"w":"The level of IgE antibodies in your blood that recognise the weeping fig (Ficus benjamina), a common indoor plant.","y":"Allergens from its leaves and sap become airborne in house dust and can cause year-round rhinitis and asthma. Weeping fig allergy can cross-react with latex and figs.","c":["Allergic rhinitis","Asthma","Latex-fruit syndrome"],"f":["Remove weeping fig plants from the home if allergy is confirmed","Dust surfaces near indoor plants regularly"],"t":["Weeping fig allergy causes year-round symptoms because the plant is kept indoors."]}$j$),
('Flour mix', $j${"w":"A screening test that measures IgE antibodies to a mix of common cereal flours in one test. A raised level shows sensitisation to at least one flour in the mix.","y":"It is a quick way to screen for sensitisation to cereals. A positive result is usually followed by single-allergen tests to find which flour is responsible."}$j$),
('Citrus fruit mix', $j${"w":"A screening test that measures IgE antibodies to a mix of citrus fruits in one test. A raised level shows sensitisation to at least one fruit in the mix.","y":"It is a quick way to screen for sensitisation to citrus fruits. A positive result is usually followed by single-allergen tests to find which fruit is responsible."}$j$),
('Grass mix', $j${"w":"A screening test that measures IgE antibodies to a mix of common grass pollens in one test. A raised level shows sensitisation to at least one grass in the mix.","y":"It is a quick way to screen for grass pollen allergy, the most common cause of hay fever in the UK. Single-allergen or component tests can then guide immunotherapy."}$j$),
('Cross-reactive carbohydrate determinants', $j${"w":"The level of IgE antibodies to cross-reactive carbohydrate determinants (CCDs), sugar side chains found on many plant, pollen and insect venom proteins.","y":"IgE to CCDs can make many allergy tests look positive without causing symptoms. A positive CCD result helps your clinician interpret other results correctly.","hi":"CCD sensitisation, which can cause false-positive allergy test results","s":"A result of 0.35 kUA/L or above shows IgE to CCDs. These antibodies rarely cause symptoms, but they can make other allergy tests look positive.","gh":"Antibodies to CCDs are present. Other positive allergy tests may reflect CCD cross-reactivity rather than true allergy.","gl":"No antibodies to CCDs were detected, so CCD cross-reactivity is unlikely to explain other positive results.","c":["Pollen allergy","Venom allergy","False-positive allergy tests"],"x":["Usually causes no symptoms"],"f":["No lifestyle changes are needed for CCD sensitisation itself"],"t":["CCD inhibition or component testing can show which positive results are clinically relevant.","CCD sensitisation is common in people with pollen or insect venom allergy."],"ug":"Call 999 if you have swelling of the face or throat, difficulty breathing or feel faint after exposure to a suspected allergen.","im":"No treatment is needed for CCD sensitisation itself. Your clinician may use component tests to check which results matter.","r":"Usually tested once, alongside other allergy tests."}$j$);
