do $$
declare k text;
begin
  select decrypted_secret into k from vault.decrypted_secrets where name = 'biomarker_lock_key' limit 1;
  if k is null or k = '' then raise exception 'Biomarker unlock key unavailable; aborting'; end if;
  perform set_config('app.biomarker_unlock', k, true);
end $$;

create temp table _tpl(g text primary key, j text) on commit drop;

create temp table _al(n text, g text, nn text, sy text, fl text) on commit drop;

create temp table _ov(n text, j jsonb) on commit drop;

select bioaudit.fill((
  select jsonb_agg(
    (replace((select j from _tpl where g = 'BASE'), '{N}', a.nn)::jsonb
      || replace((select j from _tpl where g = a.g), '{N}', a.nn)::jsonb
      || jsonb_build_object('n', a.n)
      || case when a.sy is not null then jsonb_build_object('sy', to_jsonb(string_to_array(a.sy, '|'))) else '{}'::jsonb end)
    || coalesce((select o.j from _ov o where o.n = a.n), '{}'::jsonb))
  from _al a));

update public.biomarker_hub h set related_conditions = h.related_conditions || array['Pollen food syndrome'], last_updated = now()
  from _al a where a.n = h.name and h.status = 'active' and a.fl like '%o%' and not ('Pollen food syndrome' = any(h.related_conditions));
update public.biomarker_hub h set related_conditions = h.related_conditions || array['Occupational asthma'], last_updated = now()
  from _al a where a.n = h.name and h.status = 'active' and a.fl like '%q%' and not ('Occupational asthma' = any(h.related_conditions));
update public.biomarker_hub h set related_conditions = h.related_conditions || array['Allergic bronchopulmonary aspergillosis (ABPA)'], last_updated = now()
  from _al a where a.n = h.name and h.status = 'active' and a.fl like '%a%' and not ('Allergic bronchopulmonary aspergillosis (ABPA)' = any(h.related_conditions));

select bioaudit.fill($j$[{"n":"Eosinophil Cationic Protein","y":"ECP is released when eosinophils, a type of white blood cell, are activated in allergic inflammation. It can help assess how active asthma or allergic disease is.","a":"Sample handling (clotting time and temperature), active allergy or asthma, inhaled or oral steroids, smoking and infections.","r":"T","hi":"active eosinophilic inflammation, such as poorly controlled asthma, allergic rhinitis or atopic eczema","lo":"-","u":"µg/L","b":"S","bs":"IM","c":["Asthma","Allergic rhinitis","Atopic eczema","Eosinophilic disorders"],"x":["Wheeze","Cough","Breathlessness","Itchy rash"],"f":["Take preventer inhalers as prescribed","Avoid known allergy triggers","Stop smoking"],"sy":["ECP","Serum ECP"]}]$j$::jsonb);

select set_config('app.biomarker_unlock', '', true);
